-- ============ Verbos completos: regular / irregular + cambio de vocal + conjugación (idempotente) ============
-- Clasificación según el PRESENTE (Präsens). Los verbos que ya existían solo se actualizan (conj, tipo, cambio, nota).
alter table public.words add column if not exists conj jsonb;                 -- [ich, du, er/sie/es, wir, ihr, sie/Sie]
alter table public.words add column if not exists verb_type text check (verb_type in ('regular','irregular'));
alter table public.words add column if not exists stem_change text;           -- ej. 'e→i', 'a→ä', 'au→äu', 'ehm→imm'
alter table public.words add column if not exists verb_note text;

["falle", "fällst", "fällt", "fallen", "fallt", "fallen"]'::jsonb,'irregular','a→ä','Cambio de vocal a → ä solo en du y er/sie/es; wir, ihr y sie/Sie usan la forma normal.'),
